{
  "authorities": [
    {
      "actor_class": "Selected regulated actor",
      "applicability": "PROPOSED_APPLICABLE",
      "applicability_basis": [
        {
          "quote": "This circular provides guidance to management companies of funds that are authorised by the SFC for offering to the public in Hong Kong (Funds)6 in this regard.",
          "unit_id": "d4148dd852cee.u4.564"
        },
        {
          "quote": "6 Except for listed closed-ended alternative asset funds (LAFs).",
          "unit_id": "d4148dd852cee.u63.8691"
        }
      ],
      "assumptions": [
        "Application assumes the fund falls within the circular’s definition of Funds and is not a LAF.",
        "The selected actor is understood as the fund or its management company for the classification question.",
        "Operative provision describes the circular’s prescriptive text; its independent statutory force is not established."
      ],
      "authority_id": "circular.mandatory_classification",
      "effective_from": null,
      "effective_until": null,
      "jurisdiction": "Hong Kong",
      "proposition": "A covered Fund must be classified as a complex product when its combined direct and indirect exposure to private market assets reaches or exceeds 50% of NAV. Exactly 50% meets the threshold. Exposure alone below that threshold does not establish mandatory classification under this rule.",
      "relevant_factors": [
        "SFC authorisation for public offering in Hong Kong",
        "Exclusion of LAFs",
        "Combined direct and indirect exposures",
        "Private credit and private equity",
        "50% or more of Fund NAV"
      ],
      "role_basis": [
        {
          "quote": "A Fund will be considered as a complex product if its total direct and indirect exposures to private market assets amount to 50% or more of the Fund’s NAV.",
          "unit_id": "d4148dd852cee.u21.3779"
        },
        {
          "quote": "private credit and private equity (collectively, private market assets)",
          "unit_id": "d4148dd852cee.u1.5"
        }
      ],
      "source_kind": "CIRCULAR",
      "temporal_basis": [],
      "text_role": "OPERATIVE_PROVISION",
      "treatment": "NO_TREATMENT_ESTABLISHED",
      "treatment_basis": []
    },
    {
      "actor_class": "Securities and Futures Commission",
      "applicability": "PROPOSED_APPLICABLE",
      "applicability_basis": [
        {
          "quote": "7 In cases where the Fund’s aggregate direct and indirect exposures to private market assets are less than 50% of the Fund’s NAV.",
          "unit_id": "d4148dd852cee.u64.8910"
        }
      ],
      "assumptions": [
        "No actual case-specific designation is supplied.",
        "The listed factors inform discretion; no individual factor is stated to compel designation."
      ],
      "authority_id": "circular.discretionary_designation",
      "effective_from": null,
      "effective_until": null,
      "jurisdiction": "Hong Kong",
      "proposition": "Below 50% aggregate exposure, the SFC may designate a covered Fund as complex after a holistic, case-specific assessment. Falling below 50% therefore does not establish non-complex status.",
      "relevant_factors": [
        "Aggregate direct and indirect exposures",
        "Overall investment strategy",
        "Portfolio composition",
        "Liquidity and risk profile",
        "Extent, nature and characteristics of specific asset types",
        "CLO tranches and credit ratings",
        "SRT structure, tranches and underlying assets",
        "Home-regulator distribution restrictions, requirements and conditions",
        "Other relevant circumstances; the factors are non-exhaustive"
      ],
      "role_basis": [
        {
          "quote": "On a case-by-case basis, the SFC may also designate a Fund as a complex product, taking into account factors including, without limitation:",
          "unit_id": "d4148dd852cee.u21.3779"
        },
        {
          "quote": "In assessing whether the complex product designation is warranted7, the SFC will adopt a holistic approach taking into account the specific circumstances of the case.",
          "unit_id": "d4148dd852cee.u29.4630"
        },
        {
          "quote": "the aggregate direct and indirect exposures to private market assets of the Fund;",
          "unit_id": "d4148dd852cee.u22.4078"
        },
        {
          "quote": "the Fund's overall investment strategy, portfolio composition, and liquidity and/or risk profile;",
          "unit_id": "d4148dd852cee.u24.4176"
        },
        {
          "quote": "the extent, nature and characteristics of the specific asset types in which the Fund invests (eg, the tranches and credit ratings of CLOs; the structure, tranches and underlying assets of SRTs); and",
          "unit_id": "d4148dd852cee.u26.4290"
        },
        {
          "quote": "any distribution restrictions, requirements or other conditions as may be imposed by the Fund’s home regulators.",
          "unit_id": "d4148dd852cee.u28.4505"
        }
      ],
      "source_kind": "CIRCULAR",
      "temporal_basis": [],
      "text_role": "OPERATIVE_PROVISION",
      "treatment": "NO_TREATMENT_ESTABLISHED",
      "treatment_basis": []
    },
    {
      "actor_class": "Listed closed-ended alternative asset funds (LAFs) and their management companies",
      "applicability": "INAPPLICABLE",
      "applicability_basis": [
        {
          "quote": "6 Except for listed closed-ended alternative asset funds (LAFs). For LAFs, please refer to the circular on LAFs: https://apps.sfc.hk/edistributionWeb/gateway/EN/circular/products/product-authorization/doc?refNo=25EC9",
          "unit_id": "d4148dd852cee.u63.8691"
        }
      ],
      "assumptions": [
        "INAPPLICABLE refers to application of this circular’s Funds regime to LAFs.",
        "Exclusion does not establish that LAFs are non-complex products."
      ],
      "authority_id": "circular.laf_exclusion",
      "effective_from": null,
      "effective_until": null,
      "jurisdiction": "Hong Kong",
      "proposition": "LAFs are excluded from the circular’s definition of Funds and are directed to a separate circular. Their classification cannot be determined from this retained source.",
      "relevant_factors": [
        "Whether the fund is a listed closed-ended alternative asset fund",
        "Separate LAF circular not supplied"
      ],
      "role_basis": [
        {
          "quote": "6 Except for listed closed-ended alternative asset funds (LAFs).",
          "unit_id": "d4148dd852cee.u63.8691"
        }
      ],
      "source_kind": "CIRCULAR",
      "temporal_basis": [],
      "text_role": "OPERATIVE_PROVISION",
      "treatment": "NO_TREATMENT_ESTABLISHED",
      "treatment_basis": []
    },
    {
      "actor_class": "Distributors of Funds classified as complex products",
      "applicability": "PROPOSED_APPLICABLE",
      "applicability_basis": [
        {
          "quote": "A Fund classified as a complex product will be subject to the SFC’s prevailing requirements for the sale of complex products8 including but not limited to ensuring the suitability of the Fund for its investors irrespective of whether solicitation or recommendation is involved.",
          "unit_id": "d4148dd852cee.u32.4805"
        }
      ],
      "assumptions": [
        "Application is conditional on complex-product classification.",
        "The full actor scope, exceptions and requirements of the referenced distribution instruments are not established by the supplied excerpts."
      ],
      "authority_id": "circular.distribution_consequences",
      "effective_from": null,
      "effective_until": null,
      "jurisdiction": "Hong Kong",
      "proposition": "Once classified as complex, a Fund is subject to prevailing complex-product sale requirements, including suitability irrespective of solicitation or recommendation. The circular supplies this consequence but not the full referenced distribution regime.",
      "relevant_factors": [
        "Established complex-product classification",
        "Suitability for investors",
        "Absence of solicitation or recommendation does not remove the stated suitability requirement",
        "Referenced Code of Conduct paragraph 5.5, online-platform guidelines Chapter 6 and relevant FAQs"
      ],
      "role_basis": [
        {
          "quote": "A Fund classified as a complex product will be subject to the SFC’s prevailing requirements for the sale of complex products8 including but not limited to ensuring the suitability of the Fund for its investors irrespective of whether solicitation or recommendation is involved.",
          "unit_id": "d4148dd852cee.u32.4805"
        },
        {
          "quote": "8 Paragraph 5.5 of the SFC’s Code of Conduct for Persons Licensed by or Registered with the Securities and Futures Commission and Chapter 6 of the SFC’s Guidelines on Online Distribution and Advisory Platforms, and the relevant Frequently Asked Questions.",
          "unit_id": "d4148dd852cee.u65.9044"
        }
      ],
      "source_kind": "CIRCULAR",
      "temporal_basis": [],
      "text_role": "OPERATIVE_PROVISION",
      "treatment": "NO_TREATMENT_ESTABLISHED",
      "treatment_basis": []
    },
    {
      "actor_class": "Selected regulated actor",
      "applicability": "PROPOSED_APPLICABLE",
      "applicability_basis": [
        {
          "quote": "For existing SFC-authorised funds that may have direct or indirect exposure to private market assets, fund managers are expected to undertake a review of their funds, take appropriate actions including updating the Fund’s offering documents as soon as practicable, and ensure necessary and proper communications with the distributors in light of the guidance provided under this circular (in particular, with respect to paragraphs 9 and 10 above).",
          "unit_id": "d4148dd852cee.u49.6955"
        }
      ],
      "assumptions": [
        "Application assumes an existing covered Fund with possible private-market exposure.",
        "Missing classification evidence is uncertainty, not evidence that the Fund is non-complex.",
        "The wording distinguishes expected review and action from encouraged consultation."
      ],
      "authority_id": "circular.review_and_uncertainty",
      "effective_from": null,
      "effective_until": null,
      "jurisdiction": "Hong Kong",
      "proposition": "Managers of existing covered Funds with possible private-market exposure are expected to review their funds, take appropriate action and communicate with distributors. They are encouraged to consult the SFC promptly when classification is doubtful. The supplied source does not classify any particular Fund.",
      "relevant_factors": [
        "Existing Fund status",
        "Possible direct or indirect private-market exposure",
        "Offering-document updates",
        "Distributor communications",
        "Doubt about classification"
      ],
      "role_basis": [
        {
          "quote": "fund managers are expected to undertake a review of their funds, take appropriate actions including updating the Fund’s offering documents as soon as practicable, and ensure necessary and proper communications with the distributors",
          "unit_id": "d4148dd852cee.u49.6955"
        },
        {
          "quote": "Fund managers are encouraged to consult the SFC at the earliest opportunity if they are in doubt regarding complex product classification of their Funds.",
          "unit_id": "d4148dd852cee.u49.6955"
        }
      ],
      "source_kind": "CIRCULAR",
      "temporal_basis": [
        {
          "quote": "updating the Fund’s offering documents as soon as practicable",
          "unit_id": "d4148dd852cee.u49.6955"
        }
      ],
      "text_role": "OPERATIVE_PROVISION",
      "treatment": "NO_TREATMENT_ESTABLISHED",
      "treatment_basis": []
    },
    {
      "actor_class": "Selected regulated actor",
      "applicability": "PROPOSED_APPLICABLE",
      "applicability_basis": [
        {
          "quote": "Funds with direct or indirect exposure to private market assets are required to observe the enhanced disclosure requirements set out in this circular.",
          "unit_id": "d4148dd852cee.u4.564"
        }
      ],
      "assumptions": [
        "Disclosure obligations and investment limits are distinct from the complex-product classification test.",
        "The UT Code itself has not been supplied; its complete scope and exceptions remain unverified."
      ],
      "authority_id": "circular.distinct_requirements",
      "effective_from": null,
      "effective_until": null,
      "jurisdiction": "Hong Kong",
      "proposition": "Enhanced disclosure applies to covered Funds with direct or indirect private-market exposure without a stated 50% threshold. The circular separately reports a 15% NAV investment limit for direct private-asset investments or exposures under UT Code 7.3. Neither provision substitutes for the aggregate 50% classification rule or eliminates discretionary designation below 50%.",
      "relevant_factors": [
        "Enhanced disclosure is not itself a complex-product designation",
        "15% limit concerns direct investments or exposures",
        "50% classification threshold aggregates direct and indirect exposures",
        "Examples of indirect exposures are non-exhaustive"
      ],
      "role_basis": [
        {
          "quote": "Funds with direct or indirect exposure to private market assets are required to observe the enhanced disclosure requirements set out in this circular.",
          "unit_id": "d4148dd852cee.u4.564"
        },
        {
          "quote": "1 Direct investments in/exposures to private assets fall within the investment limit of 15% of a Fund’s total net asset value (NAV) under 7.3 of the Code on Unit Trusts and Mutual Funds (UT Code).",
          "unit_id": "d4148dd852cee.u58.7778"
        },
        {
          "quote": "2 The examples of indirect exposures set out in paragraph 1 above are non-exhaustive, and subject to review and update by the SFC from time to time in view of market developments.",
          "unit_id": "d4148dd852cee.u59.7979"
        }
      ],
      "source_kind": "CIRCULAR",
      "temporal_basis": [],
      "text_role": "OPERATIVE_PROVISION",
      "treatment": "NO_TREATMENT_ESTABLISHED",
      "treatment_basis": []
    }
  ],
  "priorities": [],
  "unresolved": [
    "The retained circular’s commencement, expiry and operative status at 2026-09-28 are not established. No effective date is inferred from its URL, reference number or publication.",
    "No particular Fund’s authorisation, LAF status, portfolio exposures, NAV or SFC designation is supplied; actual classification remains unresolved.",
    "The excerpts do not specify exposure measurement, valuation timing, look-through methodology, netting or treatment of temporary threshold breaches.",
    "The separate LAF circular and complete referenced Code, guidelines and FAQs are not supplied. Their current requirements, exceptions and interaction cannot be established.",
    "Dates in footnotes 9 and 10 concern other instruments and do not establish this circular’s effectiveness.",
    "No adverse treatment, supersession or conflict is established. The threshold, discretionary designation and exclusion operate together; no displacement priority is proposed.",
    "All propositions above derive from a circular, including its references to other instruments. No independent Code provision, FAQ official answer, judicial holding or party submission is supplied.",
    "The source’s risk discussion explains the policy rationale; risk characteristics alone do not establish a case-specific designation.",
    "The packet lists three missing dependencies without their contents; their effect on classification cannot be assessed."
  ]
}
